{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "Rosaramicin, a macrocyclic lactone antibiotic, has an absolute oral bioavailability of 39 ± 8% in normal volunteers, supporting that complex polycyclic lactones can achieve F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Idarubicin, a polycyclic aromatic natural product, has an average oral bioavailability of about 30% in humans, supporting high F for complex oxygen-rich polycycles.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Artesunate, an artemisinin derivative, has an absolute oral bioavailability of 61% in Thai patients, indicating that structural modifications of poorly bioavailable polycyclic lactones can yield F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Artemisinin itself has low oral bioavailability in humans, which is a contradictory data point for the polycyclic lactone class, but the query lacks the endoperoxide responsible for this poor bioavailability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C20"],
      "claim": "5-Hydroxyrofecoxib has a very low oral bioavailability of 14% in healthy subjects, providing contradictory evidence, though the structural similarity to the query is low.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F ≥ 20%) based on moderate transferability from complex polycyclic natural products (rosaramicin 32-39%, idarubicin ~30%) and artemisinin derivatives with high F, despite low F for artemisinin itself.",
  "evidence_gaps": [
    "No direct experimental data for the query scaffold.",
    "Conflicting artemisinin data (low for parent, high for derivatives).",
    "Unknown solubility, permeability, and first-pass metabolism of the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

